#include <bits/stdc++.h>
using namespace std;

struct u99 {
    unsigned long long lo, hi;
    u99() : lo(0), hi(0) {}
    u99(unsigned long long v) : lo(v), hi(0) {}
    bool operator==(const u99 &o) const { return lo == o.lo && hi == o.hi; }
    bool operator!=(const u99 &o) const { return !(*this == o); }
    bool operator<(const u99 &o) const { return hi < o.hi || (hi == o.hi && lo < o.lo); }
    int test(int pos) const {
        if (pos < 64) return (lo >> pos) & 1;
        else return (hi >> (pos - 64)) & 1;
    }
    void set(int pos) {
        if (pos < 64) lo |= (1ULL << pos);
        else hi |= (1ULL << (pos - 64));
    }
    void reset(int pos) {
        if (pos < 64) lo &= ~(1ULL << pos);
        else hi &= ~(1ULL << (pos - 64));
    }
    u99 operator=(const u99 &o) { lo = o.lo; hi = o.hi; return *this; }
};

namespace std {
    template<> struct hash<u99> {
        size_t operator()(const u99 &v) const {
            return hash<unsigned long long>()(v.lo) ^ (hash<unsigned long long>()(v.hi) << 1);
        }
    };
}

constexpr const int mod = 1000000007;
constexpr const int inv = 570000004;
constexpr int add(int a, int b) { return a + b < mod ? a + b : a + b - mod; }
constexpr int sub(int a, int b) { return a < b ? a - b + mod : a - b; }
constexpr int mul(int a, int b) { return 1LL * a * b % mod; }

unordered_map<u99, int> name;
int n, dfn, son[65536][128];
int dfs(u99 s) {
    auto ite = name.find(s);
    if (ite != name.end()) return ite->second;
    int ret = dfn++;
    name[s] = ret;
    for (int i = 0; i != (1 << n); ++i) {
        u99 t = s;
        for (int j = 0; j != (1 << n); ++j) if (!t.test(j))
            for (int k = i & j; k; k ^= k & -k) if (s.test(j ^ (k & -k))) {
                t.set(j);
                break;
            }
        son[ret][i] = dfs(t);
    }
    return ret;
}

int p[7][7], q[7][128], dp[8][65536];

int main() {
    cin >> n;
    dfs(1);
    for (int i = 0; i != n; ++i) for (int j = 0; j != n; ++j) cin >> p[i][j], p[i][j] = mul(p[i][j], inv);
    for (int i = 0; i != n; ++i) for (int j = 0; j != (1 << n); ++j) {
        q[i][j] = 1;
        for (int k = 0; k != n; ++k) q[i][j] = mul(q[i][j], j >> k & 1 ? p[k][i] : sub(1, p[k][i]));
    }
    dp[0][0] = 1;
    for (int i = 0; i != n; ++i) for (int j = 0; j != dfn; ++j) for (int k = 0; k != (1 << n); ++k)
        dp[i + 1][son[j][k]] = add(dp[i + 1][son[j][k]], mul(dp[i][j], q[i][k]));
    u99 res;
    for (int i = 0; i != (1 << n); ++i) res.set(i);
    cout << dp[n][name[res]] << endl;
}
